/* Generic boot interface for Ami-Go ports (kit/amigo/port). The per-game parts are generated by
 * portgen.py from game.json into boot_gen.c: the memory image, start registers, chipset values and the
 * table of high-level replacements (HLE) for routines the game uses to talk to disk or the OS. */
#ifndef BOOT_H
#define BOOT_H
#include <stddef.h>
#include <stdint.h>
#ifndef BOOT_INFINITE_LIVES
#define BOOT_INFINITE_LIVES 0
#endif
const uint8_t *gamefile(const char *name, size_t *len);
/* AmigaDOS file names are case-insensitive: an embedded file is found by exact name first, then ignoring case
 * (14 Oct 2026: the shipped lookup was exact-only while the build-time lookup ignored case, so a port could pass
 * every gate and still miss a file the game asks for in a different case) */
static inline int amigo_streq_ci(const char *a, const char *b) {
    for (; *a && *b; a++, b++) { int x = *a, y = *b; if (x >= 'A' && x <= 'Z') x += 32; if (y >= 'A' && y <= 'Z') y += 32; if (x != y) return 0; }
    return *a == *b;
}   /* frontend supplies (embedded files) */
int boot_setup(uint32_t *regs, uint32_t *pc, uint16_t *sr);

/* HLE: a C function replaces the 68000 routine at `pc`. It works on the cpu_t state (cpu.h) and must
 * leave cpu.PC where the routine would have returned to (for a subroutine: pop the return address). */
typedef struct { uint32_t pc; void (*fn)(void); unsigned cycles; const char *name; } hle_t;
extern const hle_t hle_table[];
extern const int hle_count;
const hle_t *hle_find(uint32_t pc);

/* input scripts: a frame number >= SCRIPT_ANCHOR means (number - SCRIPT_ANCHOR) frames after
 * hle_last_load_frame, which a game's HLE disk loader may set (0 = not used) */
extern uint64_t hle_last_load_frame;
#define SCRIPT_ANCHOR 100000
extern const char *game_title;
#endif
